formulas.expression:
/* first populated */ 
(
not(isblank( {!$Record.LatestPrivateComment__c})) &&
isblank(PRIORVALUE( {!$Record.LatestPrivateComment__c} )) &&
NOT(ISPICKVAL({!$Record.Status},'Solved'))
)

||

/* updated */
(
ischanged( {!$Record.LatestPrivateComment__c} ) &&
not(isblank( {!$Record.LatestPrivateComment__c})) &&
NOT(ISPICKVAL({!$Record.Status}, 'Solved'))
)
